const pageSize = Number($('Page Size1').first().json.pageSize);

const rows = $input.all().filter(item =>
  item.json.id !== undefined &&
  item.json.message?.type &&
  item.json.message?.content !== undefined
);

const hasMore = rows.length > pageSize;

// Get the nearest older records, then restore chronological order.
const messages = rows
  .slice(0, pageSize)
  .reverse()
  .map(item => ({
    id: item.json.id,
    [item.json.message.type]: item.json.message.content
  }));

return [{
  json: {
    messages,
    hasMore,
    oldestId: messages[0]?.id ?? null
  }
}];
